function makeStages(slug, title) {
  const base = STAGE_SETS[slug] || STAGE_SETS['full-stack-developer'];
  if (STAGE_SETS[slug]) return base.map((s,i)=>({title:s[0],summary:s[1],topics:s.slice(2,5).map((t,j)=>({name:t,detail:`Learn and practice ${t.toLowerCase()} through small exercises.`,id:`${slug}-${i}-${j}`})),project:s[5],effort:['1–2 weeks','2–3 weeks','2–4 weeks','2–3 weeks'][i]}));
  const titleCase = title;
  const topics = [
    [`Foundations of ${titleCase}`,[`Core concepts and terminology`,`Tools and environment setup`,`Small exercises and debugging`],`Build a foundations mini-project`],
    [`Practical ${titleCase}`,[`Common workflows and patterns`,`Data, interfaces or integrations`,`Testing and error handling`],`Build a guided practical project`],
    [`Applied ${titleCase}`,[`Intermediate patterns and trade-offs`,`Use cases and real-world constraints`,`Documentation and quality checks`],`Create a portfolio-ready project`],
    [`Portfolio and mastery`,[`Review fundamentals and weak areas`,`Explain design choices and limitations`,`Publish work and prepare for interviews`],`Publish a documented capstone`]
  ];
  return topics.map((s,i)=>({title:s[0],summary:`Build toward ${titleCase.toLowerCase()} with guided practice and a concrete deliverable.`,topics:s[1].map((name,j)=>({name,detail:`Practice ${name.toLowerCase()} with a small worked example and your own notes.`,id:`${slug}-${i}-${j}`})),project:s[2],effort:['1–2 weeks','2–3 weeks','2–4 weeks','2–3 weeks'][i]}));
}

